//! The About page of the Settings window (the tray's "About EasyVox" opens it): the version and
//! EasyVox's own license, every offered model's credits, and the third-party notices for the
//! code built into the app.
//!
//! The notices file is generated by `scripts/notices.sh` (cargo-about) into
//! `packaging/THIRD_PARTY_NOTICES.html`, and `scripts/bundle.sh` copies it, with `LICENSE`, into
//! `EasyVox.app/Contents/Resources`.

use crate::model_row::{credit_with_link, linked_text, modification_with_link};
use easyvox_core::models::{self, DISCLAIMER};
use gpui_kit::component::button::Button;
use gpui_kit::component::setting::{SettingGroup, SettingItem, SettingPage};
use gpui_kit::component::{ActiveTheme as _, Sizable as _, h_flex, v_flex};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;
use std::path::PathBuf;

/// The third-party notices, in the bundle's Resources folder.
pub const NOTICES: Resource =
    Resource { bundled: "THIRD_PARTY_NOTICES.html", in_repo: "packaging/THIRD_PARTY_NOTICES.html" };
/// EasyVox's own license.
pub const LICENSE: Resource = Resource { bundled: "LICENSE.txt", in_repo: "LICENSE" };

/// A file `scripts/bundle.sh` copies into `EasyVox.app/Contents/Resources`.
#[derive(Clone, Copy)]
pub struct Resource {
    /// Its name in the bundle.
    bundled: &'static str,
    /// Where it is in the repository.
    #[cfg_attr(not(any(debug_assertions, feature = "self-test")), allow(dead_code))]
    in_repo: &'static str,
}

impl Resource {
    /// The file in the running app's bundle. Outside a bundle (`cargo run`), debug and
    /// self-test builds fall back to the repository's copy.
    pub fn path(self) -> Option<PathBuf> {
        let exe = std::env::current_exe().ok()?;
        let bundled = exe.parent()?.parent()?.join("Resources").join(self.bundled);
        if bundled.is_file() {
            return Some(bundled);
        }
        #[cfg(any(debug_assertions, feature = "self-test"))]
        {
            let repo = PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../..")).join(self.in_repo);
            if repo.is_file() {
                return Some(repo);
            }
        }
        None
    }
}

/// Opens a bundled file in its usual app (the browser for HTML). False if the build has none.
fn open(resource: Resource, cx: &mut App) -> bool {
    match resource.path() {
        Some(path) => {
            cx.open_with_system(&path);
            true
        }
        None => {
            log::warn!("{} isn't in this build (scripts/bundle.sh copies it into the app)", resource.bundled);
            false
        }
    }
}

/// How many model credits the About page drew: the self-test checks that it really draws them.
#[cfg(feature = "self-test")]
pub static DRAWN: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

const MODELS_INTRO: &str = "EasyVox downloads these models from Hugging Face when you choose them. They aren't part of \
                            EasyVox and keep their own licenses. Each one is saved with a LICENSE.txt that says the same.";

pub fn page() -> SettingPage {
    let app = SettingItem::render(|_, _, cx| {
        let muted = cx.theme().muted_foreground;
        h_flex()
            .w_full()
            .justify_between()
            .items_start()
            .gap_4()
            .child(
                v_flex()
                    .gap_0p5()
                    .child(
                        div()
                            .text_sm()
                            .font_weight(FontWeight::MEDIUM)
                            .child(format!("EasyVox {}", env!("CARGO_PKG_VERSION"))),
                    )
                    .child(
                        div().text_sm().text_color(muted).child("© 2026 Brandon Bews. Released under the MIT License."),
                    )
                    .child(
                        div()
                            .text_sm()
                            .text_color(muted)
                            .child("Speech is turned into text on this Mac: no audio or text leaves it."),
                    ),
            )
            .child(Button::new("about-license").outline().small().label("License").on_click(|_, _, cx| {
                open(LICENSE, cx);
            }))
    })
    .keywords(["version", "license", "MIT", "copyright"]);

    let mut models = SettingGroup::new().title("Speech models").description(MODELS_INTRO);
    let offered = models::offered();
    let creators = {
        let mut creators: Vec<&str> = offered.iter().map(|m| m.creator).collect();
        creators.dedup();
        creators.join(" or ")
    };
    for m in offered {
        models = models.item(
            SettingItem::render(move |_, _, cx| {
                #[cfg(feature = "self-test")]
                DRAWN.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                let muted = cx.theme().muted_foreground;
                let id = m.id;
                v_flex().gap_0p5().text_sm().child(div().font_weight(FontWeight::MEDIUM).child(m.short_name())).child(
                    v_flex()
                        .text_color(muted)
                        .child(linked_text(format!("about-{id}-credit"), &format!("{}.", credit_with_link(m)), px(4.)))
                        .child(linked_text(
                            format!("about-{id}-card"),
                            &format!("Original model: [{}]({})", without_scheme(m.card_url), m.card_url),
                            px(4.),
                        ))
                        .child(linked_text(
                            format!("about-{id}-changes"),
                            &format!("{}.", modification_with_link(m)),
                            px(4.),
                        ))
                        .child(DISCLAIMER),
                )
            })
            .keywords([m.name, m.creator, m.license.name, "credits", "attribution"]),
        );
    }
    models = models.footer(move |_, cx| {
        div()
            .text_xs()
            .text_color(cx.theme().muted_foreground)
            .child(format!("EasyVox isn't affiliated with or endorsed by {creators}."))
    });

    let notices = SettingItem::render(|_, _, cx| {
        let found = NOTICES.path().is_some();
        h_flex()
            .w_full()
            .justify_between()
            .items_start()
            .gap_4()
            .child(div().text_sm().text_color(cx.theme().muted_foreground).child(
                "EasyVox is built on open-source software: GPUI (Zed Industries), GPUI Kit (Longbridge), \
                     transcribe.cpp and ggml, SQLite, Lucide icons and about 450 Rust crates. Their licenses \
                     and notices are in one file.",
            ))
            .child(
                Button::new("about-notices")
                    .outline()
                    .small()
                    .label("Third-party notices")
                    .when(!found, |b| b.tooltip("Not in this build: scripts/bundle.sh copies it into the app."))
                    .on_click(|_, _, cx| {
                        open(NOTICES, cx);
                    }),
            )
    })
    .keywords(["open source", "third-party", "notices", "licenses", "acknowledgements"]);

    SettingPage::new("About")
        .group(SettingGroup::new().title("EasyVox").item(app))
        .group(models)
        .group(SettingGroup::new().title("Open-source software").item(notices))
}

/// "huggingface.co/nvidia/parakeet-tdt-0.6b-v2" for a link's text.
fn without_scheme(url: &str) -> &str {
    url.strip_prefix("https://").unwrap_or(url)
}
